function applyV8Scores(){
 if(typeof FOODS==='undefined') return;
 FOODS.forEach(f=>{
   let hit=null;
   // exact / contained name matching, longer keys first
   for(const k of Object.keys(V8_SCORE_OVERRIDES).sort((a,b)=>b.length-a.length)){
     if(f.name===k || f.name.includes(k)){hit=V8_SCORE_OVERRIDES[k];break}
   }
   if(hit){
     [f.head,f.sparkle,f.muscle,f.bone,f.immunity]=hit;
     f.score_rule_version=SCORE_RULE_VERSION;
     f.score_status='reviewed_v8';
   }else{
     // Do not allow unreviewed heuristic ★★★ to masquerade as top-tier.
     // Cap legacy 3 -> 2 until official food-row mapping is reviewed.
     ['head','sparkle','muscle','bone','immunity'].forEach(k=>{if(f[k]===3)f[k]=2});
     f.score_rule_version=SCORE_RULE_VERSION;
     f.score_status='provisional_capped';
   }
 });
}
applyV8Scores();

